<script setup lang="ts">
import { Head, router, useForm } from '@inertiajs/vue3'; import InventoryNav from '../../Components/Common/InventoryNav.vue';
interface User{id:number;name:string;email:string;active:boolean;last_login_at:string|null;roles:string[]} interface Role{id:number;name:string;permissions:string[]} interface Employee{id:number;employee_code:string;first_name:string;last_name:string;department:string|null;job_title:string|null;active:boolean;user_email:string|null}
const props=defineProps<{users:User[];roles:Role[];permissions:string[];employees:Employee[]}>();
const user=useForm({name:'',email:'',password:'',password_confirmation:'',roles:[] as string[]}); const role=useForm({name:'',permissions:[] as string[]}); const employee=useForm({employee_code:'',national_id:'',first_name:'',last_name:'',email:'',phone:'',address:'',hire_date:'',department:'',job_title:'',monthly_salary:0,user_id:'' as number|string});
const saveUser=()=>user.post('/access/users',{onSuccess:()=>user.reset()}); const saveRole=()=>role.post('/access/roles',{onSuccess:()=>role.reset()}); const saveEmployee=()=>employee.post('/access/employees',{onSuccess:()=>employee.reset()});
const editUser=(u:User)=>{const name=prompt('Nombre',u.name);if(!name)return;const email=prompt('Correo',u.email);if(!email)return;router.put(`/access/users/${u.id}`,{name,email,password:'',password_confirmation:'',roles:u.roles,active:!u.active?true:u.active},{preserveScroll:true})};
const toggleEmployee=(e:Employee)=>router.patch(`/access/employees/${e.id}/active`,{active:!e.active},{preserveScroll:true});
const editRole=(r:Role)=>{const selected=prompt('Permisos separados por coma',r.permissions.join(','));if(selected===null)return;router.put(`/access/roles/${r.id}`,{permissions:selected.split(',').map(x=>x.trim()).filter(Boolean)},{preserveScroll:true})};
</script>
<template><Head title="Usuarios, roles y empleados"/><main class="page"><InventoryNav/><h1>Usuarios, roles y empleados</h1><div class="columns"><section class="card"><h2>Nuevo usuario</h2><form class="form" @submit.prevent="saveUser"><label>Nombre<input v-model="user.name" required></label><label>Correo<input v-model="user.email" type="email" required></label><label>Contraseña<input v-model="user.password" type="password" minlength="8" required></label><label>Confirmación<input v-model="user.password_confirmation" type="password" required></label><fieldset><legend>Roles</legend><label v-for="r in roles" :key="r.id" class="check"><input v-model="user.roles" type="checkbox" :value="r.name">{{r.name}}</label></fieldset><button>Crear usuario</button><p class="error">{{Object.values(user.errors)[0]}}</p></form></section><section class="card"><h2>Nuevo rol</h2><form class="form" @submit.prevent="saveRole"><label>Nombre<input v-model="role.name" required></label><fieldset class="permissions"><legend>Permisos</legend><label v-for="p in permissions" :key="p" class="check"><input v-model="role.permissions" type="checkbox" :value="p">{{p}}</label></fieldset><button>Crear rol</button><p class="error">{{Object.values(role.errors)[0]}}</p></form></section></div><section class="card table"><h2>Usuarios</h2><table><thead><tr><th>Nombre</th><th>Correo</th><th>Roles</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td>{{u.name}}</td><td>{{u.email}}</td><td>{{u.roles.join(', ')}}</td><td>{{u.active?'Activo':'Inactivo'}}</td><td><button @click="editUser(u)">Editar</button></td></tr></tbody></table><h2>Roles</h2><table><tbody><tr v-for="r in roles" :key="r.id"><td>{{r.name}}</td><td>{{r.permissions.length}} permisos</td><td><button @click="editRole(r)">Editar permisos</button></td></tr></tbody></table></section><section class="card"><h2>Nuevo empleado</h2><form class="employee" @submit.prevent="saveEmployee"><label>Código *<input v-model="employee.employee_code" required></label><label>Identidad<input v-model="employee.national_id"></label><label>Nombres *<input v-model="employee.first_name" required></label><label>Apellidos *<input v-model="employee.last_name" required></label><label>Departamento<input v-model="employee.department"></label><label>Cargo<input v-model="employee.job_title"></label><label>Fecha de ingreso<input v-model="employee.hire_date" type="date"></label><label>Salario mensual<input v-model.number="employee.monthly_salary" type="number" min="0" step=".01"></label><label>Usuario vinculado<select v-model="employee.user_id"><option value="">Sin usuario</option><option v-for="u in users" :key="u.id" :value="u.id">{{u.name}} — {{u.email}}</option></select></label><label>Teléfono<input v-model="employee.phone"></label><button>Guardar empleado</button></form></section><section class="card table"><h2>Empleados</h2><table><thead><tr><th>Código</th><th>Nombre</th><th>Área / cargo</th><th>Usuario</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="e in employees" :key="e.id"><td>{{e.employee_code}}</td><td>{{e.first_name}} {{e.last_name}}</td><td>{{e.department||'—'}} / {{e.job_title||'—'}}</td><td>{{e.user_email||'—'}}</td><td>{{e.active?'Activo':'Inactivo'}}</td><td><button class="danger" @click="toggleEmployee(e)">{{e.active?'Desactivar':'Activar'}}</button></td></tr></tbody></table></section></main></template>
<style scoped>.page{max-width:1500px;margin:auto;padding:2rem}.columns{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.card{padding:1.5rem;border:1px solid var(--p-content-border-color);border-radius:1rem;margin:1rem 0;background:var(--p-content-background)}.form,.employee{display:grid;gap:.8rem}.employee{grid-template-columns:repeat(2,minmax(0,1fr))}label{display:grid;gap:.3rem;font-weight:600}input,select{padding:.7rem;border:1px solid var(--p-content-border-color);border-radius:.5rem;background:transparent;color:inherit}.check{display:flex;align-items:center;gap:.4rem;font-weight:400}.permissions{max-height:20rem;overflow:auto}.table{overflow:auto}table{width:100%;border-collapse:collapse}td,th{padding:.7rem;border-bottom:1px solid var(--p-content-border-color);text-align:left}button{width:max-content;padding:.65rem .9rem;border:0;border-radius:.5rem;background:var(--p-primary-color);color:var(--p-primary-contrast-color);font-weight:700}.danger{background:#ef4444}.error{color:#ef4444}@media(max-width:800px){.columns,.employee{grid-template-columns:1fr}}</style>
